[metadata] {"type": "create", "filePath": "/app/output/final_report.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>IPL 2026 Ball-by-Ball Analytics Report</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>
<style>
  :root {
    --bg: #0d1117;
    --surface: #161b22;
    --surface2: #1f2937;
    --border: #30363d;
    --accent: #f97316;
    --accent2: #06b6d4;
    --accent3: #a855f7;
    --green: #22c55e;
    --red: #ef4444;
    --yellow: #eab308;
    --text: #e6edf3;
    --muted: #8b949e;
    --card-shadow: 0 4px 24px rgba(0,0,0,0.4);
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { background: var(--bg); color: var(--text); font-family: 'Segoe UI', system-ui, sans-serif; font-size: 14px; line-height: 1.6; }

  /* Layout */
  .container { max-width: 1400px; margin: 0 auto; padding: 0 24px; }
  header { background: linear-gradient(135deg, #1a0a2e 0%, #0d1117 50%, #0f1f2e 100%); border-bottom: 1px solid var(--border); padding: 40px 0 32px; }
  header .container { display: flex; flex-direction: column; gap: 8px; }
  .header-badge { background: var(--accent); color: #000; font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; padding: 3px 10px; border-radius: 4px; width: fit-content; }
  header h1 { font-size: 2.2rem; font-weight: 800; color: #fff; letter-spacing: -0.5px; }
  header p { color: var(--muted); font-size: 0.95rem; max-width: 700px; }
  .header-meta { display: flex; gap: 20px; margin-top: 8px; flex-wrap: wrap; }
  .header-meta span { color: var(--muted); font-size: 0.85rem; }
  .header-meta strong { color: var(--text); }
  nav { background: var(--surface); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 100; }
  nav .container { display: flex; gap: 0; overflow-x: auto; }
  nav a { color: var(--muted); text-decoration: none; padding: 12px 18px; font-size: 0.85rem; font-weight: 500; white-space: nowrap; border-bottom: 2px solid transparent; transition: all .2s; }
  nav a:hover { color: var(--text); border-color: var(--accent); }
  main { padding: 40px 0 80px; }
  section { margin-bottom: 64px; }
  .section-header { margin-bottom: 28px; }
  .section-tag { font-size: 11px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--accent); margin-bottom: 6px; }
  section h2 { font-size: 1.6rem; font-weight: 700; color: #fff; }
  section p.desc { color: var(--muted); margin-top: 6px; max-width: 800px; }

  /* Cards */
  .card { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 24px; box-shadow: var(--card-shadow); }
  .card-sm { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 18px 20px; }

  /* KPI Dashboard */
  .kpi-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 16px; }
  .kpi-card { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 20px; position: relative; overflow: hidden; }
  .kpi-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 3px; }
  .kpi-card.c1::before { background: var(--accent); }
  .kpi-card.c2::before { background: var(--accent2); }
  .kpi-card.c3::before { background: var(--accent3); }
  .kpi-card.c4::before { background: var(--green); }
  .kpi-card.c5::before { background: var(--yellow); }
  .kpi-label { font-size: 11px; font-weight: 600; text-transform: uppercase; letter-spacing: 1px; color: var(--muted); margin-bottom: 10px; }
  .kpi-value { font-size: 2.2rem; font-weight: 800; line-height: 1; }
  .kpi-card.c1 .kpi-value { color: var(--accent); }
  .kpi-card.c2 .kpi-value { color: var(--accent2); }
  .kpi-card.c3 .kpi-value { color: var(--accent3); }
  .kpi-card.c4 .kpi-value { color: var(--green); }
  .kpi-card.c5 .kpi-value { color: var(--yellow); }
  .kpi-sub { font-size: 0.78rem; color: var(--muted); margin-top: 6px; }

  /* Overview grid */
  .overview-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; margin-bottom: 32px; }
  .stat-card { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 18px 20px; text-align: center; }
  .stat-card .val { font-size: 2rem; font-weight: 800; color: var(--accent2); }
  .stat-card .lbl { font-size: 0.78rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.5px; margin-top: 4px; }

  /* Charts grid */
  .chart-2col { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; }
  .chart-3col { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 20px; }
  .chart-wrap { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: 20px; }
  .chart-title { font-size: 0.85rem; font-weight: 600; color: var(--text); margin-bottom: 16px; text-transform: uppercase; letter-spacing: 0.5px; }
  .chart-container { position: relative; }

  /* Tables */
  .table-wrap { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
  table { width: 100%; border-collapse: collapse; }
  thead tr { background: var(--surface2); }
  thead th { padding: 12px 14px; text-align: left; font-size: 11px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: var(--muted); border-bottom: 1px solid var(--border); }
  tbody tr { border-bottom: 1px solid var(--border); transition: background .15s; }
  tbody tr:last-child { border-bottom: none; }
  tbody tr:hover { background: rgba(255,255,255,0.03); }
  tbody td { padding: 11px 14px; font-size: 0.88rem; }
  .rank { color: var(--muted); font-weight: 600; width: 32px; }
  .player-name { font-weight: 600; color: var(--text); }
  .team-tag { display: inline-block; background: rgba(249,115,22,0.15); color: var(--accent); font-size: 10px; font-weight: 700; padding: 1px 6px; border-radius: 4px; margin-left: 6px; }
  .highlight { color: var(--accent); font-weight: 700; }
  .badge { display: inline-block; padding: 2px 8px; border-radius: 4px; font-size: 11px; font-weight: 700; }
  .badge-green { background: rgba(34,197,94,0.15); color: var(--green); }
  .badge-red { background: rgba(239,68,68,0.15); color: var(--red); }
  .badge-yellow { background: rgba(234,179,8,0.15); color: var(--yellow); }
  .badge-blue { background: rgba(6,182,212,0.15); color: var(--accent2); }

  /* Bar mini */
  .bar-mini-wrap { margin-top: 4px; }
  .bar-mini { height: 5px; border-radius: 3px; background: var(--border); overflow: hidden; }
  .bar-mini-fill { height: 100%; border-radius: 3px; }

  /* Phase cards */
  .phase-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-bottom: 28px; }
  .phase-card { border-radius: 12px; padding: 22px; border: 1px solid; }
  .phase-card.pp { background: rgba(6,182,212,0.07); border-color: rgba(6,182,212,0.25); }
  .phase-card.mid { background: rgba(168,85,247,0.07); border-color: rgba(168,85,247,0.25); }
  .phase-card.death { background: rgba(249,115,22,0.07); border-color: rgba(249,115,22,0.25); }
  .phase-name { font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; margin-bottom: 12px; }
  .phase-card.pp .phase-name { color: var(--accent2); }
  .phase-card.mid .phase-name { color: var(--accent3); }
  .phase-card.death .phase-name { color: var(--accent); }
  .phase-rr { font-size: 2.4rem; font-weight: 800; line-height: 1; margin-bottom: 6px; }
  .phase-card.pp .phase-rr { color: var(--accent2); }
  .phase-card.mid .phase-rr { color: var(--accent3); }
  .phase-card.death .phase-rr { color: var(--accent); }
  .phase-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px; }
  .phase-stat { }
  .phase-stat-val { font-size: 1.1rem; font-weight: 700; }
  .phase-stat-lbl { font-size: 10px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.5px; }

  /* Dismissal donut */
  .two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
  .three-col { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 24px; }

  /* Match cards */
  .matches-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 14px; }
  .match-card { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 16px; }
  .match-no { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--muted); margin-bottom: 8px; }
  .match-teams { display: flex; align-items: center; justify-content: space-between; margin-bottom: 8px; }
  .match-team { text-align: center; }
  .match-team-name { font-size: 1rem; font-weight: 800; color: var(--text); }
  .match-team-score { font-size: 1.4rem; font-weight: 800; color: var(--accent2); }
  .match-vs { color: var(--muted); font-size: 0.8rem; font-weight: 600; }
  .match-meta { font-size: 0.75rem; color: var(--muted); margin-top: 6px; }
  .match-abandoned { background: rgba(239,68,68,0.08); border-color: rgba(239,68,68,0.3); }

  /* Venue */
  .venue-row { display: grid; grid-template-columns: 2.5fr 1fr 1fr 1fr 1fr 1.5fr; gap: 12px; align-items: center; padding: 14px 16px; border-bottom: 1px solid var(--border); }
  .venue-row:last-child { border-bottom: none; }
  .venue-row-hdr { background: var(--surface2); font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; color: var(--muted); border-radius: 8px 8px 0 0; }
  .venue-name-short { font-size: 0.82rem; color: var(--text); font-weight: 600; }
  .venue-city { font-size: 0.75rem; color: var(--muted); }

  /* Responsive */
  @media (max-width: 1100px) {
    .kpi-grid { grid-template-columns: repeat(3, 1fr); }
    .chart-3col { grid-template-columns: 1fr 1fr; }
    .matches-grid { grid-template-columns: repeat(2, 1fr); }
  }
  @media (max-width: 768px) {
    .kpi-grid { grid-template-columns: 1fr 1fr; }
    .chart-2col, .two-col, .three-col, .phase-grid, .overview-grid { grid-template-columns: 1fr; }
    .matches-grid { grid-template-columns: 1fr; }
    header h1 { font-size: 1.5rem; }
  }

  /* Scrollbar */
  ::-webkit-scrollbar { width: 6px; height: 6px; }
  ::-webkit-scrollbar-track { background: var(--bg); }
  ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

  /* Heatmap */
  .heatmap-grid { display: grid; gap: 3px; }
  .heatmap-cell { border-radius: 3px; display: flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 600; color: rgba(255,255,255,0.8); }

  /* Inline SVG progress */
  .progress-bar { height: 8px; background: var(--border); border-radius: 4px; overflow: hidden; margin-top: 6px; }
  .progress-fill { height: 100%; border-radius: 4px; }

  /* Footer */
  footer { border-top: 1px solid var(--border); padding: 24px 0; margin-top: 40px; }
  footer p { color: var(--muted); font-size: 0.8rem; text-align: center; }
</style>
</head>
<body>

<header>
  <div class="container">
    <div class="header-badge">IPL 2026 · Partial Season</div>
    <h1>Ball-by-Ball Analytics Report</h1>
    <p>Delivery-level insights covering 15 matches across 10 venues — batting, bowling, dismissals, extras discipline, and venue trends for analysts and team strategists.</p>
    <div class="header-meta">
      <span><strong>Season:</strong> IPL 2026 (19th Edition)</span>
      <span><strong>Period:</strong> Mar 28 – Apr 9, 2026</span>
      <span><strong>Deliveries Analyzed:</strong> 3,284</span>
      <span><strong>Stage:</strong> League Stage</span>
      <span><strong>Source:</strong> krishd123/ipl-2026-complete-dataset</span>
    </div>
  </div>
</header>

<nav>
  <div class="container">
    <a href="#kpis">KPIs</a>
    <a href="#overview">Overview</a>
    <a href="#batting">Batting</a>
    <a href="#bowling">Bowling</a>
    <a href="#teams">Teams</a>
    <a href="#extras">Extras</a>
    <a href="#venues">Venues</a>
    <a href="#matches">Matches</a>
  </div>
</nav>

<main>
<div class="container">

<!-- ═══════════════════ KPIs ═══════════════════ -->
<section id="kpis">
  <div class="section-header">
    <div class="section-tag">Dashboard</div>
    <h2>Tournament KPIs</h2>
    <p class="desc">Five headline metrics derived from all 3,284 deliveries across 15 matches.</p>
  </div>

  <div class="kpi-grid">
    <div class="kpi-card c1">
      <div class="kpi-label">Avg Runs Per Over</div>
      <div class="kpi-value">9.72</div>
      <div class="kpi-sub">Total runs ÷ total overs (526)</div>
      <div class="progress-bar" style="margin-top:12px"><div class="progress-fill" style="width:97%;background:var(--accent)"></div></div>
    </div>
    <div class="kpi-card c2">
      <div class="kpi-label">Boundary %</div>
      <div class="kpi-value">21.5%</div>
      <div class="kpi-sub">706 boundary deliveries / 3,284 total</div>
      <div class="progress-bar" style="margin-top:12px"><div class="progress-fill" style="width:71%;background:var(--accent2)"></div></div>
    </div>
    <div class="kpi-card c3">
      <div class="kpi-label">Dot Ball %</div>
      <div class="kpi-value">31.4%</div>
      <div class="kpi-sub">1,030 dot balls (0 bat, 0 extras)</div>
      <div class="progress-bar" style="margin-top:12px"><div class="progress-fill" style="width:63%;background:var(--accent3)"></div></div>
    </div>
    <div class="kpi-card c4">
      <div class="kpi-label">Extras Per Match</div>
      <div class="kpi-value">17.7</div>
      <div class="kpi-sub">266 total extras / 15 matches</div>
      <div class="progress-bar" style="margin-top:12px"><div class="progress-fill" style="width:59%;background:var(--green)"></div></div>
    </div>
    <div class="kpi-card c5">
      <div class="kpi-label">Wickets Per Match</div>
      <div class="kpi-value">12.0</div>
      <div class="kpi-sub">180 total wickets / 15 matches</div>
      <div class="progress-bar" style="margin-top:12px"><div class="progress-fill" style="width:60%;background:var(--yellow)"></div></div>
    </div>
  </div>
</section>

<!-- ═══════════════════ OVERVIEW ═══════════════════ -->
<section id="overview">
  <div class="section-header">
    <div class="section-tag">Section 1</div>
    <h2>Tournament Overview &amp; Match Summary</h2>
    <p class="desc">Aggregate snapshot of the IPL 2026 season through 15 league matches played across all 10 franchises.</p>
  </div>

  <div class="overview-grid">
    <div class="stat-card"><div class="val">15</div><div class="lbl">Matches Played</div></div>
    <div class="stat-card"><div class="val">3,284</div><div class="lbl">Total Deliveries</div></div>
    <div class="stat-card"><div class="val">5,114</div><div class="lbl">Total Runs Scored</div></div>
    <div class="stat-card"><div class="val">180</div><div class="lbl">Wickets Fallen</div></div>
    <div class="stat-card"><div class="val">10</div><div class="lbl">Teams</div></div>
    <div class="stat-card"><div class="val">10</div><div class="lbl">Venues</div></div>
    <div class="stat-card"><div class="val">4,848</div><div class="lbl">Runs off the Bat</div></div>
    <div class="stat-card"><div class="val">266</div><div class="lbl">Extras Conceded</div></div>
  </div>

  <!-- Match Phase Overview Chart -->
  <div class="chart-2col">
    <div class="chart-wrap">
      <div class="chart-title">Run Distribution by Phase</div>
      <div class="chart-container" style="height:220px">
        <canvas id="phaseRunsChart"></canvas>
      </div>
    </div>
    <div class="chart-wrap">
      <div class="chart-title">Dismissal Types Breakdown</div>
      <div class="chart-container" style="height:220px">
        <canvas id="dismissalChart"></canvas>
      </div>
    </div>
  </div>
</section>

<!-- ═══════════════════ BATTING ═══════════════════ -->
